/**
 * @ohos/dsh-boot-report — one-shot runtime capability report.
 *
 * The phone has no terminal: when the model answers "I cannot search the
 * web", there is no way to tell whether the tool is missing from the registry,
 * registered but not ready (no credential), or simply unused. This plugin
 * writes that answer into `bridge.log` a few seconds after boot:
 *
 *   [boot-report] tools(12): glob,grep,read,write,run_code,web_fetch,web_search,…
 *   [boot-report] web: search=ready (deepseek-official) fetch=ready (http)
 *
 * `web` is read through `ctx.get('web')` rather than `inject` on purpose: the
 * report must still print when the web seam itself failed to load, which is
 * exactly the case worth diagnosing. The seam (dsh 0.2.1-rc.4) exposes
 * provider registries (`searchProviders` / `fetchProviders`, Maps of
 * `{id, available()}`) plus the configured id (`config.<x>Provider.get()` or
 * `DSH_WEB_<X>_PROVIDER`); readiness is derived from those without any
 * network call — `searchReady()`/`fetchReady()` do not exist in this dsh.
 *
 * Read-only, no timers after the first run, and it never throws into boot.
 */
const name = "boot-report-ohos";
const inject = ["tools"];

/** Delay: late enough for `when`-gated tools (web_search) to settle. */
const REPORT_DELAY_MS = 5000;

function isAvailable(provider) {
	try {
		return provider.available() === true;
	} catch (error) {
		return false;
	}
}

function readConfigured(web, kind) {
	try {
		const slice =
			kind === "search" ? web.config?.searchProvider : web.config?.fetchProvider;
		const value = slice?.get?.();
		return typeof value === "string" && value.length > 0 ? value : undefined;
	} catch (error) {
		return undefined;
	}
}

function envConfigured(web, kind) {
	try {
		const value =
			kind === "search" ? web.searchProviderEnv : web.fetchProviderEnv;
		return typeof value === "string" && value.length > 0 ? value : undefined;
	} catch (error) {
		return undefined;
	}
}

/**
 * Describe one capability (search|fetch) from the seam's registries.
 * Mirrors the service's own provider resolution without touching the
 * network: the configured id first, then exactly-one-available logic.
 */
function describeCapability(web, kind) {
	const providers =
		kind === "search" ? web.searchProviders : web.fetchProviders;
	if (!(providers instanceof Map)) {
		return "unknown (unexpected seam shape)";
	}
	const configured = readConfigured(web, kind) ?? envConfigured(web, kind);
	if (configured !== undefined) {
		const provider = providers.get(configured);
		if (provider === undefined) {
			return `configured "${configured}" not registered`;
		}
		return isAvailable(provider)
			? `ready (${configured})`
			: `configured "${configured}" unavailable`;
	}
	const usable = [];
	const unavailable = [];
	for (const provider of providers.values()) {
		if (isAvailable(provider)) {
			usable.push(provider.id);
		} else {
			unavailable.push(`${provider.id}(unavailable)`);
		}
	}
	if (usable.length === 0) {
		return unavailable.length > 0
			? `registered but unavailable: ${unavailable.join(",")}`
			: "no provider registered";
	}
	if (usable.length > 1) {
		return `ambiguous: ${usable.join(",")}`;
	}
	return `ready (${usable[0]})`;
}

async function report(ctx) {
	const tag = "[boot-report]";
	try {
		const schemas = ctx.tools.schemas();
		const names = schemas
			.map((schema) => schema.name)
			.filter((tool) => typeof tool === "string")
			.sort();
		console.log(`${tag} tools(${names.length}): ${names.join(",")}`);
	} catch (error) {
		console.log(`${tag} tools: unavailable (${error?.message ?? error})`);
	}

	try {
		const web = ctx.get("web");
		if (web === undefined) {
			console.log(`${tag} web: seam absent (tool-web never loaded)`);
			return;
		}
		const search = describeCapability(web, "search");
		const fetch = describeCapability(web, "fetch");
		console.log(`${tag} web: search=${search} fetch=${fetch}`);
	} catch (error) {
		console.log(`${tag} web: probe failed (${error?.message ?? error})`);
	}
}

function apply(ctx) {
	const timer = setTimeout(() => {
		report(ctx).catch(() => {});
	}, REPORT_DELAY_MS);
	if (typeof timer.unref === "function") timer.unref();
	ctx.effect(() => () => clearTimeout(timer));
}

export { name, inject, apply, describeCapability };
